/**
 * SLA Task Escalation Flow
 *
 * This flow monitors SLA task progress and escalates based on completion percentage:
 *
 * At 75% of SLA time:
 * - If task not assigned: Update work notes with warning
 * - If task assigned: Update work notes and send notification to assignment group manager
 *
 * At 90% of SLA time:
 * - If resolved: Update work notes with resolution confirmation
 * - If not resolved: Update work notes, send notification to manager + assigned user + CC second level manager
 *
 * After resolution:
 * - Wait for task to be resolved
 * - Send confirmation notification to all previously notified parties
 *
 * Triggers on SLA task events
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const slaTaskEscalationFlow = Flow(
    {
        $id: Now.ID['sla_task_escalation_flow'],
        name: 'SLA Task Escalation Flow',
        description: 'Monitors and escalates SLA tasks at 75% and 90% completion thresholds',
    },
    wfa.trigger(trigger.application.slaTask, { $id: Now.ID['sla_task_trigger'] }, {}),
    (params) => {
        // Wait until SLA reaches 75% of actual elapsed percentage
        wfa.action(
            action.core.slaPercentageTimer,
            {
                $id: Now.ID['wait_75_percent'],
                annotation: 'Wait for 75% of SLA time',
            },
            {
                percentage: 75,
            }
        )

        // Look up the SLA record to get the task reference
        const slaRecord = wfa.action(
            action.core.lookUpRecord,
            {
                $id: Now.ID['lookup_sla_record_75'],
                annotation: 'Retrieve SLA record to get task reference',
            },
            {
                table: 'task_sla',
                conditions: `sys_id=${wfa.dataPill(params.trigger.task_sla_record, 'records')}`,
            }
        )

        // Look up the task record using the task reference from SLA
        const taskRecord = wfa.action(
            action.core.lookUpRecord,
            {
                $id: Now.ID['lookup_task_record_75'],
                annotation: 'Retrieve task record at 75% SLA',
            },
            {
                table: 'task',
                conditions: `sys_id=${wfa.dataPill(slaRecord.Record.task, 'reference')}`,
            }
        )

        // Check if task is not assigned
        wfa.flowLogic.if(
            {
                condition: `${wfa.dataPill(taskRecord.Record.assigned_to, 'reference')}=NULL`,
                annotation: 'Check if task is not assigned at 75% SLA',
                $id: Now.ID['check_not_assigned_75'],
            },
            () => {
                // Update work notes - task not assigned
                wfa.action(
                    action.core.updateRecord,
                    {
                        $id: Now.ID['update_work_notes_not_assigned_75'],
                        annotation: 'Update work notes for unassigned task at 75% SLA',
                    },
                    {
                        table_name: 'task',
                        record: `${wfa.dataPill(taskRecord.Record.sys_id, 'reference')}`,
                        values: TemplateValue({
                            work_notes: 'Incident not assigned at 75% of SLA time.',
                        }),
                    }
                )
            }
        )

        // Else - task is assigned
        wfa.flowLogic.else(
            {
                annotation: 'Handle assigned task at 75% SLA',
                $id: Now.ID['handle_assigned_75'],
            },
            () => {
                // Update work notes - task assigned but needs attention
                wfa.action(
                    action.core.updateRecord,
                    {
                        $id: Now.ID['update_work_notes_assigned_75'],
                        annotation: 'Update work notes for assigned task at 75% SLA',
                    },
                    {
                        table_name: 'task',
                        record: `${wfa.dataPill(taskRecord.Record.sys_id, 'reference')}`,
                        values: TemplateValue({
                            work_notes: 'Incident not assigned at 75% of SLA time.',
                        }),
                    }
                )

                // Look up assignment group to get manager
                const assignmentGroup = wfa.action(
                    action.core.lookUpRecord,
                    {
                        $id: Now.ID['lookup_assignment_group_75'],
                        annotation: 'Retrieve assignment group for manager lookup',
                    },
                    {
                        table: 'sys_user_group',
                        conditions: `sys_id=${wfa.dataPill(taskRecord.Record.assignment_group, 'reference')}`,
                    }
                )

                // Look up manager details
                wfa.action(
                    action.core.lookUpRecord,
                    {
                        $id: Now.ID['lookup_manager_75'],
                        annotation: 'Retrieve manager details for escalation',
                    },
                    {
                        table: 'sys_user',
                        conditions: `sys_id=${wfa.dataPill(assignmentGroup.Record.manager, 'reference')}`,
                    }
                )

                // Send escalation notification to manager
                wfa.action(
                    action.core.sendNotification,
                    {
                        $id: Now.ID['send_escalation_notification_75'],
                        annotation: 'Send SLA escalation notification to manager at 75%',
                    },
                    {
                        table_name: 'task',
                        record: `${wfa.dataPill(taskRecord.Record.sys_id, 'reference')}`,
                        notification: 'sla_escalation_level_1_notification',
                    }
                )
            }
        )

        // Wait until SLA reaches 90% of actual elapsed percentage
        wfa.action(
            action.core.slaPercentageTimer,
            {
                $id: Now.ID['wait_90_percent'],
                annotation: 'Wait for 90% of SLA time',
            },
            {
                percentage: 90,
            }
        )

        // Look up the SLA record again to get the task reference at 90%
        const slaRecord90 = wfa.action(
            action.core.lookUpRecord,
            {
                $id: Now.ID['lookup_sla_record_90_for_task'],
                annotation: 'Retrieve SLA record to get task reference at 90%',
            },
            {
                table: 'task_sla',
                conditions: `sys_id=${wfa.dataPill(params.trigger.task_sla_record, 'records')}`,
            }
        )

        // Look up the task record again at 90%
        const taskRecord90 = wfa.action(
            action.core.lookUpRecord,
            {
                $id: Now.ID['lookup_task_record_90'],
                annotation: 'Retrieve task record at 90% SLA',
            },
            {
                table: 'task',
                conditions: `sys_id=${wfa.dataPill(slaRecord90.Record.task, 'reference')}`,
            }
        )

        // Check if task state is Resolved (6)
        wfa.flowLogic.if(
            {
                condition: `${wfa.dataPill(taskRecord90.Record.state, 'string')}=6`,
                annotation: 'Check if task is resolved at 90% SLA',
                $id: Now.ID['check_resolved_90'],
            },
            () => {
                // Update work notes - task resolved
                wfa.action(
                    action.core.updateRecord,
                    {
                        $id: Now.ID['update_work_notes_resolved_90'],
                        annotation: 'Update work notes for resolved task at 90% SLA',
                    },
                    {
                        table_name: 'task',
                        record: `${wfa.dataPill(taskRecord90.Record.sys_id, 'reference')}`,
                        values: TemplateValue({
                            work_notes: 'Incident resolved at or before 90% of SLA time.',
                        }),
                    }
                )
            }
        )

        // Else - task not resolved at 90%
        wfa.flowLogic.else(
            {
                annotation: 'Handle unresolved task at 90% SLA',
                $id: Now.ID['handle_not_resolved_90'],
            },
            () => {
                // Update work notes - task not resolved
                wfa.action(
                    action.core.updateRecord,
                    {
                        $id: Now.ID['update_work_notes_not_resolved_90'],
                        annotation: 'Update work notes for unresolved task at 90% SLA',
                    },
                    {
                        table_name: 'task',
                        record: `${wfa.dataPill(taskRecord90.Record.sys_id, 'reference')}`,
                        values: TemplateValue({
                            work_notes: 'Incident not resolved by 90% SLA time.',
                        }),
                    }
                )

                // Look up assignment group to get manager
                const assignmentGroup90 = wfa.action(
                    action.core.lookUpRecord,
                    {
                        $id: Now.ID['lookup_assignment_group_90'],
                        annotation: 'Retrieve assignment group for escalation',
                    },
                    {
                        table: 'sys_user_group',
                        conditions: `sys_id=${wfa.dataPill(taskRecord90.Record.assignment_group, 'reference')}`,
                    }
                )

                // Look up first level manager
                const manager90 = wfa.action(
                    action.core.lookUpRecord,
                    {
                        $id: Now.ID['lookup_manager_90'],
                        annotation: 'Retrieve first level manager details',
                    },
                    {
                        table: 'sys_user',
                        conditions: `sys_id=${wfa.dataPill(assignmentGroup90.Record.manager, 'reference')}`,
                    }
                )

                // Look up assigned user
                wfa.action(
                    action.core.lookUpRecord,
                    {
                        $id: Now.ID['lookup_assigned_user_90'],
                        annotation: 'Retrieve assigned user details',
                    },
                    {
                        table: 'sys_user',
                        conditions: `sys_id=${wfa.dataPill(taskRecord90.Record.assigned_to, 'reference')}`,
                    }
                )

                // Look up second level manager
                wfa.action(
                    action.core.lookUpRecord,
                    {
                        $id: Now.ID['lookup_second_level_manager_90'],
                        annotation: 'Retrieve second level manager details',
                    },
                    {
                        table: 'sys_user',
                        conditions: `sys_id=${wfa.dataPill(manager90.Record.manager, 'reference')}`,
                    }
                )

                // Send urgent escalation notification to manager, assigned user, and CC second level manager
                wfa.action(
                    action.core.sendNotification,
                    {
                        $id: Now.ID['send_urgent_escalation_notification_90'],
                        annotation: 'Send urgent escalation notification at 90% SLA',
                    },
                    {
                        table_name: 'task',
                        record: wfa.dataPill(taskRecord90.Record.sys_id, 'reference'),
                        notification: 'sla_escalation_urgent_notification',
                    }
                )

                // Wait for the task state to be updated to Resolved (6)
                wfa.action(
                    action.core.waitForCondition,
                    {
                        $id: Now.ID['wait_for_resolution'],
                        annotation: 'Wait for task to be resolved',
                    },
                    {
                        table_name: 'task',
                        record: `${wfa.dataPill(taskRecord90.Record.sys_id, 'reference')}`,
                        conditions: 'state=6',
                        timeout_duration: '7 00:00:00',
                    }
                )

                // Look up the SLA record to get task reference after resolution
                const slaRecordResolved = wfa.action(
                    action.core.lookUpRecord,
                    {
                        $id: Now.ID['lookup_sla_record_resolved'],
                        annotation: 'Retrieve SLA record for actual elapsed percentage',
                    },
                    {
                        table: 'task_sla',
                        conditions: `sys_id=${wfa.dataPill(params.trigger.task_sla_record, 'records')}`,
                    }
                )

                // Look up the task record after resolution
                const taskRecordResolved = wfa.action(
                    action.core.lookUpRecord,
                    {
                        $id: Now.ID['lookup_task_record_resolved'],
                        annotation: 'Retrieve task record after resolution',
                    },
                    {
                        table: 'task',
                        conditions: `sys_id=${wfa.dataPill(slaRecordResolved.Record.task, 'reference')}`,
                    }
                )

                // Send resolution confirmation notification to all previously notified parties
                wfa.action(
                    action.core.sendNotification,
                    {
                        $id: Now.ID['send_resolution_confirmation_notification'],
                        annotation: 'Send resolution confirmation notification',
                    },
                    {
                        table_name: 'task',
                        record: `${wfa.dataPill(taskRecordResolved.Record.sys_id, 'reference')}`,
                        notification: 'sla_resolution_confirmation_notification',
                    }
                )
            }
        )
    }
)
